package android.content;
public class ClipData { private final ClipDescription description; private final java.util.ArrayList<Item> items=new java.util.ArrayList<Item>(); public ClipData(CharSequence label,String[] types,Item item) { this(new ClipDescription(label,types),item); } public ClipData(ClipDescription d,Item i) { description=d; items.add(i); } public static ClipData newPlainText(CharSequence label,CharSequence text) { return new ClipData(label,new String[]{ClipDescription.MIMETYPE_TEXT_PLAIN},new Item(text)); } public static ClipData newRawUri(CharSequence label,android.net.Uri uri) { return new ClipData(label,new String[]{ClipDescription.MIMETYPE_TEXT_URILIST},new Item(uri)); } public static ClipData newIntent(CharSequence label,Intent intent) { return new ClipData(label,new String[]{ClipDescription.MIMETYPE_TEXT_INTENT},new Item(intent)); } public ClipDescription getDescription() { return description; } public int getItemCount() { return items.size(); } public Item getItemAt(int i) { return items.get(i); } public void addItem(Item i) { items.add(i); } public static class Item { private CharSequence text; private Intent intent; private android.net.Uri uri; public Item(CharSequence t) { text=t; } public Item(Intent i) { intent=i; } public Item(android.net.Uri u) { uri=u; } public CharSequence getText() { return text; } public Intent getIntent() { return intent; } public android.net.Uri getUri() { return uri; } public CharSequence coerceToText(Context c) { return text!=null?text:uri!=null?uri.toString():intent!=null?intent.toString():""; } } }
